<?php
require_once __DIR__.'/advanced.php';
function e($v): string { return htmlspecialchars((string)$v,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8'); }
function csrf_field(): string { $_SESSION['csrf']??=bin2hex(random_bytes(32));return '<input type="hidden" name="_csrf" value="'.e($_SESSION['csrf']).'">'; }
function csrf_check(): void { if(empty($_SESSION['csrf']) || !is_string($_POST['_csrf']??null) || !hash_equals($_SESSION['csrf'],$_POST['_csrf']))throw new RuntimeException('Your session expired. Reload the page and try again.'); }
function current_user(): ?array { if(empty($_SESSION['user_id']))return null;$q=db()->prepare('SELECT user_id,full_name,email,role,auth_version FROM users WHERE user_id=? AND account_status="active"');$q->execute([$_SESSION['user_id']]);$u=$q->fetch();if(!$u){unset($_SESSION['user_id'],$_SESSION['auth_version']);return null;}if(!isset($_SESSION['auth_version']))$_SESSION['auth_version']=(int)$u['auth_version'];if((int)$_SESSION['auth_version']!==(int)$u['auth_version']){unset($_SESSION['user_id'],$_SESSION['auth_version']);return null;}return $u; }
function require_login(): array { $u=current_user();if(!$u){flash('Please sign in to continue.','warning');redirect('?page=login');}return $u; }
function require_role(string $role): array { $u=require_login();if($u['role']!==$role){http_response_code(403);exit('Access denied');}return $u; }
function redirect(string $url): never { header('Location: '.$url);exit; }
function flash(string $message,string $type='success'): void { $_SESSION['flashes'][]=['message'=>$message,'type'=>$type]; }
function flashes(): array { $f=$_SESSION['flashes']??[];unset($_SESSION['flashes']);return $f; }
function notify(int $user,string $message,string $type, int $id): void { $q=db()->prepare('INSERT INTO notifications(user_id,message,related_type,related_id) VALUES(?,?,?,?)');$q->execute([$user,$message,$type,$id]); }
function product(int $id): ?array { $q=db()->prepare('SELECT p.*,c.category_name,(SELECT image_path FROM product_images WHERE product_id=p.product_id ORDER BY is_primary DESC LIMIT 1) image FROM products p LEFT JOIN categories c USING(category_id) WHERE product_id=?');$q->execute([$id]);return $q->fetch()?:null; }
function active_cart(int $uid): int { $q=db()->prepare('SELECT cart_id FROM carts WHERE user_id=? AND cart_status="active" ORDER BY cart_id DESC LIMIT 1');$q->execute([$uid]);$id=$q->fetchColumn();if($id)return (int)$id;$q=db()->prepare('INSERT INTO carts(user_id,cart_status) VALUES(?,"active")');$q->execute([$uid]);return (int)db()->lastInsertId(); }
function money($v): string { return '$'.number_format((float)$v,2); }
