  <section class="hero rounded-4 p-4 p-md-5 mb-5"><div class="col-lg-7 py-5"><span class="eyebrow">Furniture for real life</span><h1 class="display-4 fw-semibold mt-3">Design your space.<br>Customize your comfort.</h1><p class="lead my-4">Discover beautiful furniture or create a unique piece that perfectly matches your style.</p><a class="btn btn-primary btn-lg me-2" href="?page=shop">Explore collection</a><?php $homeUser=current_user();if($homeUser&&$homeUser['role']==='customer'):?><a class="btn btn-outline-dark btn-lg" href="?page=custom-request">Create custom furniture</a><?php endif;?></div></section>
