  case 'shop': $where=['p.availability<>"Archived"'];$params=[];$s=trim($_GET['q']??'');if($s){$where[]='(p.name LIKE ? OR p.description LIKE ?)';$params[]="%$s%";$params[]="%$s%";}if(!empty($_GET['category'])){$where[]='p.category_id=?';$params[]=(int)$_GET['category'];}if(!empty($_GET['customizable']))$where[]='p.is_customizable=1';if(isset($_GET['min'])&&$_GET['min']!==''){$where[]='p.base_price>=?';$params[]=(float)$_GET['min'];}if(isset($_GET['max'])&&$_GET['max']!==''){$where[]='p.base_price<=?';$params[]=(float)$_GET['max'];}$sort=['low'=>'p.base_price ASC','high'=>'p.base_price DESC','name'=>'p.name ASC','new'=>'p.created_at DESC'][$_GET['sort']??'new']??'p.created_at DESC';$q=db()->prepare('SELECT p.*,c.category_name,(SELECT image_path FROM product_images WHERE product_id=p.product_id ORDER BY is_primary DESC LIMIT 1) image FROM products p LEFT JOIN categories c USING(category_id) WHERE '.implode(' AND ',$where).' ORDER BY '.$sort);$q->execute($params);$items=$q->fetchAll();?><h1>Shop the collection</h1><form class="row g-2 my-4"><input type="hidden" name="page" value="shop"><div class="col-md-4"><input class="form-control" name="q" placeholder="Search furniture" value="<?=e($s)?>"></div><div class="col-md-2"><select class="form-select" name="category"><option value="">All categories</option><?php foreach(db()->query('SELECT * FROM categories ORDER BY category_name') as $c):?><option value="<?=$c['category_id']?>" <?=($_GET['category']??'')==$c['category_id']?'selected':''?>><?=e($c['category_name'])?></option><?php endforeach;?></select></div><div class="col-md-2"><input class="form-control" name="min" type="number" placeholder="Min price"></div><div class="col-md-2"><select class="form-select" name="sort"><option value="new">Newest</option><option value="low">Price: low to high</option><option value="high">Price: high to low</option><option value="name">Name: A to Z</option></select></div><div class="col-md-2"><button class="btn btn-primary w-100">Filter<