  case 'cart': $u=require_role('customer');$cart=active_cart($u['user_id']);$q=db()->prepare('SELECT ci.*,p.name,p.product_id,(SELECT image_path FROM product_images WHERE product_id=p.product_id ORDER BY is_primary DESC LIMIT 1) image FROM cart_items ci JOIN products p USING(product_id) WHERE ci.cart_id=?');$q->execute([$cart]);$rows=$q->fetchAll();foreach($rows as &$item){$cx=db()->prepare("SELECT selected_value FROM cart_item_customizations WHERE cart_item_id=?");$cx->execute([$item["cart_item_id"]]);$item["customizations"]=$cx->fetchAll(PDO::FETCH_COLUMN);$cc=db()->prepare('SELECT component_label,spec_json FROM cart_item_component_snapshots WHERE cart_item_id=? ORDER BY snapshot_id');$cc->execute([$item['cart_item_id']]);$item['component_specs']=$cc->fetchAll();}unset($item);$total=0;?><h1>Your cart</h1><?php if(!$rows):?><div class="empty">Your cart is waiting for something lovely. <a href="?page=shop">Browse the collection</a></div><?php else:?><form method="post"><?=csrf_field()?><input type="hidden" name="action" value="update_cart"><div class="table-responsive"><table class="table align-middle"><thead><tr><th>Piece</th><th>Unit price</th><th>Quantity</th><th>Subtotal</th><th></th></tr></thead><tbody><?php foreach($rows as $r):$sub=$r['unit_price']*$r['quantity'];$total+=$sub;?><tr><td><a href="?page=product&id=<?=$r['product_id']?>"><?=e($r['name'])?></a><?php foreach($r['customizations'] as $choice):?><div class="small text-muted"><?=e($choice)?></div><?php endforeach;?><?php foreach($r['component_specs'] as $cs):?><div class="small component-snapshot"><?=e(format_component_snapshot($cs['spec_json']))?></div><?php endforeach;?></td><td><?=money($r['unit_price'])?></td><td><input class="form-control" style="width:90px" name="qty[<?=$r['cart_item_id']?>]" type="number" min="1" value="<?=$r['quantity']?>"></td><td><?=money($sub)?></td><td><button class="btn btn-sm btn-outline-danger" type="submit" formaction="?page=cart" formmethod="post" name="remove" value="<?=$r['cart_item_id']?>" onclick="this.form.elements['action'].value='remove_cart';this.form.item_id.value=this.value">Remove</button></td></tr><?php endforeach;?></tbody></table></div><input type="hidden" name="item_id" value=""><button class="btn btn-outline-dark">Update cart</button></form><div class="text-end mt-4"><h3>Total: <?=money($total)?></h3><a class="btn btn-primary btn-lg" href="?page=checkout">Continue to checkout</a></div><?php endif;?><?php break;
