ry->execute([$r['request_id'],$u['user_id']]);foreach($history as $review):?><p class="small mt-2"><b><?=e($review['feasibility'])?></b> · <?=e($review['review_date'])?><br><?=nl2br(e($review['technical_notes']))?><?php if($review['material_availability']):?><br>Materials: <?=e($review['material_availability'])?><?php endif;?><?php if($review['estimated_time']):?> · Time: <?=e($review['estimated_time'])?><?php endif;?><?php if($review['recommended_modifications']):?><br>Recommendations: <?=e($review['recommended_modifications'])?><?php endif;?></p><?php endforeach;?></details><?php endif;?><?php if($u['role']==='admin'):?><details class="mt-3"><summary>Manufacturer reviews and create quotation</summary><?php $q=db()->prepare('SELECT mr.*,u.full_name FROM manufacturer_reviews mr JOIN users u ON u.user_id=mr.manufacturer_id WHERE request_id=? ORDER BY review_date DESC');$q->execute([$r['request_id']]);foreach($q as $rv):?><p><?=e($rv['full_name'])?>: <?=e($rv['feasibility'])?> — <?=e($rv['technical_notes'])?></p><?php endforeach;?><form method="post" class="row g-2 mt-2"><?=csrf_field()?><input type="hidden" name="action" value="quotation"><input type="hidden" name="request_id" value="<?=$r['request_id']?>"><div class="col-md-2"><input class="form-control" name="price" type="number" step="0.01" min="0.01" placeholder="Price" required></div><div class="col-md-3"><input class="form-control" name="estimated_time" placeholder="Lead time" required></div><div class="col-md-3"><input class="form-control" name="valid_until" type="date"></div><div class="col-md-4"><input class="form-control" name="notes" placeholder="Notes"></div><div class="col-12"><button class="btn btn-outline-dark" name="save" value="1">Save draft</button> <button class="btn btn-primary" name="send" value="1">Send quotation</button></div></form></details><?php endif;?></div><?php endforeach;if(!$rs)echo '<div class="empty">No requests here yet.</div>';break;
  case 'quotations': $u=require_login();if($u['role']==='customer'){$q=db()->prepare('SELECT q.*,cr.title,cr.furniture_type FROM quotations q JOIN custom_requests cr USING(request_id) WHERE cr.user_id=? ORDER BY q.created_at DESC');$q->execute([$u['user_id']]);}elseif($u['role']==='admin'){$q=db()->query('SELECT q.*,cr.title,cr.furniture_type FROM quotations q JOIN custom_requests cr USING(request_id) ORDER BY q.created_at DESC');}else{http_response_code(403);exit('Access denied');}?><h1>Quotations</h1><?php foreach($q as $x):?><div class="card p-3 mb-3"><h4>Request #<?=$x['request_id']?> · <?=e($x['title']?:$x['furniture_type'])?></h4><strong><?=money($x['price'])?></strong><p><?=e($x['estimated_time'])?> · <?=e($x['status'])?> · Valid until <?=e($x['valid_until']??'—')?></p><p><?=e($x['notes'])?></p><?php if($u['role']==='customer'&&$x['status']==='Sent'):?><form method="post" class="d-flex gap-2"><?=csrf_field()?><input type="hidden" name="action" value="quotation_reply"><input type="hidden" name="quotation_id" value="<?=$x['quotation_id']?>"><label>Delivery address <input class="form-control" name="address" maxlength="1000" required></label><button name="status" value="Accepted" class="btn btn-primary">Accept</button><button formnovalidate name="status" value="Rejected" class="btn btn-outline-danger">Decline</button></form><?php endif;?></div><?php endforeach;?><?php break;
  case 'orders': require_role('admin');$orders=db()->query('SELECT o.*,u.full_name FROM orders o JOIN users u USING(user_id) ORDER BY order_date DESC')->fetchAll();?><h1>Orders</h1><?php foreach($orders as $o):?><div class="card p-3 mb-2 d-flex flex-row justify-content-between align-items-center"><div><b>#<?=$o['order_id']?> · <?=e($o['full_name'])?></b> — <?=money($o['total_amount'])?> <span class="badge text-bg-light"><?=e($o['status'])?></span></div><form method="post" class="d-flex gap-2" onsubmit="return this.elements.status.value !== 'Cancelled' || confirm('Cancel this order?')"><?=csrf_field()?><input type="hidden" name="action" value="status"><input type="hidden" name="order_id" value="<?=$o['order_id']?>"><select class="form-select" name="status"><?php foreach(['Confirmed','Processing','Manufacturing','Shipped','Delivered','Cancelled'] as $s):?><option><?=$s?></option><?php endforeach;?></select><button class="btn btn-primary">Update</button></form></div><?php endforeach;?><?php break;
  case 'users': require_role('admin');$users=db()->query('SELECT user_id,full_name,email,phone,role,account_status,created_at FROM users ORDER BY created_at DESC')->fetchAll();?><h1>Users</h1><div class="table-responsive"><table class="table align-middle"><thead><tr><th>Name</th><th>Email</th><th>Phone</th><th>Role</th><th>Status</th><th>Joined</th><th>Action</th></tr></thead><tbody><?php foreach($users as $u):?><tr><td><?=e($u['full_name'])?></td><td><?=e($u['email'])?></td><td><?=e($u['phone']??'')?></td><td><?=e(ucfirst($u['role']))?></td><td><?=e(ucfirst($u['account_status']))?></td><td><?=e($u['created_at'])?></td><td><?php if($u['role']!=='admin'):?><form method="post" onsubmit="return confirm('Change this account’s active status?')"><?=csrf_field()?><input type="hidden" name="action" value="user_toggle"><input type="hidden" name="user_id" value="<?=$u['user_id']?>"><button class="btn btn-sm btn-outline-dark"><?=$u['account_status']==='active'?'Deactivate':'Activate'?></button></form><?php else:?><span class="text-muted small">Protected</span><?php endif;?></td></tr><?php endforeach;?></tbody></table></div><?php break;
  case 'notifications': $u=require_login();$q=db()->prepare('SELECT * FROM notifications WHERE user_id=? ORDER BY created_at DESC');$q->execute([$u['user_id']]);?><h1>Notifications</h1><?php foreach($q as $n):?><div class="card p-3 mb-2 <?= $n['is_read']?'':'border-primary'?>"><div class="d-flex justify-content-between"><span><?=e($n['message'])?> <small class="text-secondary">· <?=e($n['created_at'])?></small></span><?php if(!$n['is_read']):?><form method="post"><?=csrf_field()?><input type="hidden" name="action" value="read_notification"><input type="hidden" name="notification_id" value="<?=$n['notification_id']?>"><button class="btn btn-sm btn-outline-dark">Mark read</button></form><?php endif;?></div></div><?php endforeach;?><?php break;
  default: http_response_code(404);echo '<div class="empty"><h1>Page not found</h1><a href="?">Return home</a></div>'; }
}
function furniflex_model_url(int $productId): ?string { $models=[1=>'assets/models/arden_sofa_innerscene.glb',2=>'assets/models/milo_coffee_table_cove_122.glb',3=>'assets/models/haven_spindle_frame_bed.glb',4=>'assets/models/linden_wingfold_butterfly_table_cc0.glb',5=>'assets/models/studio_desk_innerscene.glb',8=>'assets/models/modular_wardrobe.glb'];$path=$models[$productId]??null;if(!$path)return null;$file=dirname(__DIR__).'/'.$path;$version=is_file($file)?(string)filemtime($file):'1';return $path.'?v='.$version; }
function furniflex_fallback_image(): string { return 'assets/images/furniture-fallback.svg'; }
function furniflex_product_image(array $product): string { return furniflex_fallback_image(); }
function render_product_visual(array $product,string $class=''): void { ?><img class="<?=e($class)?>" src="<?=e(furniflex_fallback_image())?>" alt="<?=e($product['name'])?>" loading="eager" decoding="async"><?php }
function render_model_fallback(array $product): void { ?><img class="preview-fallback" src="<?=e(furniflex_fallback_image())?>" alt="<?=e($product['name'])?>" loading="eager" decoding="async" fetchpriority="high"><?php }
function card(array $x): void { $id=(int)$x['product_id'];$details='?page=product&id='.$id;$customize='?page=customize&id='.$id; ?><div class="col-12 col-sm-6 col-lg-3"><article class="product-card"><a class="product-card-main" href="<?=e($details)?>" aria-label="View details for <?=e($x['name'])?>"><?php if($model=furniflex_model_url($id)):?><div class="model-preview model-preview-card furniflex-3d-preview" data-product-id="<?=$id?>" data-product-name="<?=e($x['name'])?>" data-model-url="<?=e($model)?>"><canvas aria-label="3D preview of <?=e($x['name'])?>"></canvas><?php render_model_fallback($x); ?><span class="model-loading">Loading 3D preview…</span></div><?php else:?><?php render_product_visual($x); ?><?php endif;?><div class="p-3"><small class="eyebrow"><?=e($x['category_name']??'Furniture')?></small><h5 class="mt-1"><?=e($x['name'])?></h5><strong><?=money($x['base_price'])?></strong><span class="product-card-details-hint">View product details <i class="bi bi-arrow-right"></i></span></div></a><div class="product-card-action"><a class="product-details-action" href="<?=e($details)?>">Product details</a><?php if(!empty($x['is_customizable'])):?><a class="btn btn-primary" href="<?=e($customize)?>">Customize</a><?php endif;?></div></article></div><?php }

function render_product_details_page(array $x): void {
    $id=(int)$x['product_id'];
    $model=furniflex_model_url($id);
    $components=component_definitions($id);
    $dimensionQuery=db()->prepare('SELECT dimension_name,default_cm FROM product_dimension_rules WHERE product_id=? ORDER BY FIELD(dimension_name,"width","height","depth")');
    $dimensionQuery->execute([$id]);
    $dimensionValues=[];
    foreach($dimensionQuery->fetchAll() as $dimension)$dimensionValues[$dimension['dimension_name']]=(float)$dimension['default_cm'];
    $materials=array_values(array_unique(array_filter(array_map(static fn($c)=>trim((string)($c['default_material']??'')),$components))));
    $finishes=array_values(array_unique(array_filter(array_map(static fn($c)=>trim((string)($c['default_finish']??'')),$components))));
    $colors=array_values(array_unique(array_filter(array_map(static fn($c)=>strtoupper((string)($c['default_color_hex']??'')),$components),static fn($v)=>preg_match('/^#[0-9A-F]{6}$/',$v)===1)));
    $specs=[];
    if($dimensionValues){$parts=[];foreach(['width'=>'W','height'=>'H','depth'=>'D'] as $key=>$label)if(isset($dimensionValues[$key]))$parts[]=$label.' '.rtrim(rtrim(number_format($dimensionValues[$key],1,'.',''),'0'),'.').' cm';$specs['Dimensions']=implode(' · ',$parts);}
    if($materials)$specs['Materials']=implode(', ',$materials);
    if($finishes)$specs['Finish']=implode(', ',$finishes);
    if($colors)$specs['Color options']=implode(', ',$colors);
    $sku=trim((string)($x['sku']??$x['product_code']??''));
    if($sku!=='')$specs['Product code']=$sku;
    $weight=$x['weight_kg']??$x['weight']??null;
    if(is_numeric($weight)&&(float)$weight>0)$specs['Weight']=rtrim(rtrim(number_format((float)$weight,2,'.',''),'0'),'.').' kg';
    $category=trim((string)($x['category_name']??''));
    $categoryUrl='?page=shop'.(!empty($x['category_id'])?'&category='.(int)$x['category_id']:'');
    $relatedQuery=db()->prepare('SELECT p.*,c.category_name,(SELECT image_path FROM product_images WHERE product_id=p.product_id ORDER BY is_primary DESC LIMIT 1) image FROM products p LEFT JOIN categories c USING(category_id) WHERE p.product_id<>? AND p.availability<>"Archived" ORDER BY (p.category_id=?) DESC,p.created_at DESC LIMIT 4');
    $relatedQuery->execute([$id,(int)($x['category_id']??0)]);
    $related=$relatedQuery->fetchAll();
    $user=current_user();
    ?>
    <section class="product-detail-premium">
      <nav aria-label="Breadcrumb" class="product-breadcrumb"><ol class="breadcrumb"><li class="breadcrumb-item"><a href="?">Home</a></li><li class="breadcrumb-item"><a href="?page=shop">Shop</a></li><?php if($category!==''):?><li class="breadcrumb-item"><a href="<?=e($categoryUrl)?>"><?=e($category)?></a></li><?php endif;?><li class="breadcrumb-item active" aria-current="page"><?=e($x['name'])?></li></ol></nav>
      <div class="row g-4 g-xl-5 align-items-stretch product-detail-hero">
        <div class="col-lg-7"><div class="product-detail-gallery">
          <?php if($model):?><div class="model-preview product-hero-model furniflex-3d-preview" data-product-id="<?=$id?>" data-product-name="<?=e($x['name'])?>" data-model-url="<?=e($model)?>"><canvas aria-label="Interactive 3D model of <?=e($x['name'])?>"></canvas><?php render_model_fallback($x); ?><span class="model-loading">Preparing 3D preview…</span></div><div class="product-viewer-caption"><i class="bi bi-mouse"></i> Drag to rotate <span>·</span> Scroll to zoom</div><?php else:?><?php render_product_visual($x,'product-detail rounded-4'); ?><?php endif;?>
        </div></div>
        <div class="col-lg-5"><div class="product-detail-summary">
          <div class="product-detail-category"><i class="bi bi-house-door"></i> <?=e($category?:'Furniture')?></div>
          <h1><?=e($x['name'])?></h1>
          <?php if(!empty($x['description'])):?><p class="product-detail-intro"><?=e($x['description'])?></p><?php endif;?>
          <div class="product-detail-price-row"><strong class="product-detail-price"><?=money($x['base_price'])?></strong><span class="availability-pill <?=($x['availability']??'')==='In Stock'?'is-in-stock':'is-unavailable'?>"><i class="bi bi-circle-fill"></i><?=e($x['availability']??'Availability unavailable')?></span></div>
          <div class="product-detail-highlights"><h2>Designed for your space</h2><div class="product-highlight-list"><?php if($model):?><span><i class="bi bi-badge-3d"></i> Interactive 3D preview</span><?php endif;?><?php if($components):?><span><i class="bi bi-sliders"></i> <?=count($components)?> configurable components</span><span><i class="bi bi-palette2"></i> Component material and color options</span><?php endif;?><span><i class="bi bi-check2-circle"></i> <?=e($x['availability']??'Availability not listed')?></span></div></div>
          <div class="product-detail-actions"><?php if(!empty($x['is_customizable'])):?><a class="btn btn-primary btn-lg" href="?page=customize&id=<?=$id?>">Customize This Product <i class="bi bi-arrow-up-right"></i></a><?php endif;?>
          <?php if($user&&$user['role']==='customer'):?><form method="post" class="product-detail-cart-form"><?=csrf_field()?><input type="hidden" name="action" value="add_cart"><input type="hidden" name="product_id" value="<?=$id?>"><label class="visually-hidden" for="product-quantity">Quantity</label><input id="product-quantity" class="form-control" type="number" min="1" max="99" value="1" name="quantity"><button class="btn btn-outline-dark btn-lg" type="submit"><i class="bi bi-bag-plus"></i> Add to Cart</button></form><?php else:?><a class="btn btn-outline-dark btn-lg" href="?page=login"><i class="bi bi-bag-plus"></i> Sign in to order</a><?php endif;?></div>
        </div></div>
      </div>
      <div class="row g-4 mt-4 product-detail-lower">
        <?php if(!empty($x['description'])):?><section class="col-lg-7"><div class="product-info-panel product-description-panel"><span class="eyebrow">The piece</span><h2>About this product</h2><p><?=nl2br(e($x['description']))?></p><?php if($components):?><h3>Customizable details</h3><div class="component-chip-list"><?php foreach($components as $component):?><span><?=e($component['display_name'])?></span><?php endforeach;?></div><?php endif;?></div></section><?php endif;?>
        <?php if($specs):?><section class="col-lg-5"><div class="product-info-panel"><span class="eyebrow">Product information</span><h2>Specifications</h2><dl class="product-spec-list"><?php foreach($specs as $label=>$value):?><div><dt><?=e($label)?></dt><dd><?=e($value)?></dd></div><?php endforeach;?></dl></div></section><?php endif;?>
      </div>
      <?php if($related):?><section class="related-products"><div class="related-heading"><div><span class="eyebrow">Continue exploring</span><h2>Related pieces</h2></div><a href="<?=e($categoryUrl)?>">Shop <?=e($category?:'collection')?> <i class="bi bi-arrow-right"></i></a></div><div class="row g-3"><?php foreach($related as $item)card($item);?></div></section><?php endif;?>
    </section>
    <?php
}
function table(array $rows,array $cols): void { if(!$rows){echo '<div class="empty">Nothing to show yet.</div>';return;}?><div class="table-responsive"><table class="table table-hover"><thead><tr><?php foreach($cols as $t):?><th><?=e($t)?></th><?php endforeach;?></tr></thead><tbody><?php foreach($rows as $r):?><tr><?php foreach($cols as $k=>$t):?><td><?=e($r[$k]??'—')?></td><?php endforeach;?></tr><?php endforeach;?></tbody></table></div><?php }


